import React, { useRef, useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import SalonCard from "../../components/common/SalonCard";
import TabBar from "../../components/common/TabBar";
import promotionHeader from "../../images/promotionHeader.png"; // ✅ Correct image import

const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 1380px;
  padding: 20px 0 60px;
`;

const WelcomeText = styled.h1`
  font-family: "Inter", sans-serif;
  font-size: 44px;
  font-weight: 700;
  color: #27374d;
  margin: 40px 0 30px;
`;

const PromoBanner = styled.div`
  width: 100%;
  height: 220px;
  border-radius: 12px;
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
  margin-bottom: 40px;
`;

const BannerImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 12px;
`;

const BookNowButton = styled.button`
  position: absolute;
  bottom: 20px;
  left: 20px;
  background-color: #0b1c36;
  color: white;
  font-size: 16px;
  font-weight: 500;
  padding: 10px 18px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: 0.2s ease;
  &:hover {
    opacity: 0.9;
  }
`;

const SectionTitle = styled.h2`
  font-size: 22px;
  font-weight: 600;
  color: #2d2d2d;
  margin: 30px 0 16px;
`;

const ScrollWrapper = styled.div`
  position: relative;
  display: flex;
  align-items: center;
`;

const HorizontalScroll = styled.div`
  display: flex;
  gap: 18px;
  overflow-x: hidden;
  scroll-behavior: smooth;
  width: 100%;
  padding-bottom: 10px;
`;

const ScrollCircle = styled.div`
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: white;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  position: absolute;
  right: -20px;
  z-index: 10;
  transition: 0.2s ease;
  &:hover {
    transform: scale(1.05);
    background-color: #f4f4f4;
  }
`;

const ArrowIcon = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="20"
    height="20"
    fill="none"
    stroke="#000"
    strokeWidth="2"
    viewBox="0 0 24 24"
  >
    <path d="M9 18l6-6-6-6" />
  </svg>
);

const HomePage: React.FC = () => {
  const navigate = useNavigate();

  const salons = [
    { id: "hair-avenue", image: "/images/hairavenue.jpg", name: "Hair Avenue", distance: "2.3 km", location: "No 03, Kadalana Road, Kadalana, Moratuwa", rating: 4.7, reviews: 312 },
    { id: "blend-salon", image: "/images/blend.jpg", name: "Blend Salon", distance: "1.5 km", location: "45 Queen’s Street, Colombo", rating: 4.8, reviews: 280 },
    { id: "hair-place", image: "/images/hairplace.jpg", name: "Hair Place", distance: "2.3 km", location: "No 03, Kadalana Road, Kadalana, Moratuwa", rating: 4.7, reviews: 312 },
    { id: "fresh-salon", image: "/images/freshsalon.jpg", name: "Fresh Salon", distance: "1.5 km", location: "45 Queen’s Street, Colombo", rating: 4.8, reviews: 280 },
    { id: "hair-forever", image: "/images/hairforever.jpg", name: "Hair Forever", distance: "2.3 km", location: "No 03, Kadalana Road, Kadalana, Moratuwa", rating: 4.7, reviews: 312 },
    { id: "man-salon", image: "/images/mansalon.jpg", name: "Man Salon", distance: "1.5 km", location: "45 Queen’s Street, Colombo", rating: 4.8, reviews: 280 },
  ];

  // Control scroll position
  const scrollRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [scrollPositions, setScrollPositions] = useState<number[]>([]);

  const CARDS_PER_PAGE = 4;
  const CARD_WIDTH = 298; // 280 card + 18px gap approximation

  const handleScrollRight = (index: number) => {
    const container = scrollRefs.current[index];
    if (container) {
      container.scrollBy({ left: CARD_WIDTH * CARDS_PER_PAGE, behavior: "smooth" });
      setScrollPositions((prev) => {
        const newPositions = [...prev];
        newPositions[index] = (newPositions[index] || 0) + 1;
        return newPositions;
      });
    }
  };

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        <WelcomeText>Welcome Back, Enid!</WelcomeText>

        {/* ✅ Promotion banner image fixed */}
        <PromoBanner>
          <BannerImage src={promotionHeader} alt="Promotion" />
          <BookNowButton>Book Now</BookNowButton>
        </PromoBanner>

        {["Trending Now", "Near You", "For Her", "For Him"].map((category, index) => {
          // Determine which 4-card slice to show based on scroll index
          const start = (scrollPositions[index] || 0) * CARDS_PER_PAGE;
          const visibleSalons = salons.slice(start, start + CARDS_PER_PAGE);
          const hasMore = start + CARDS_PER_PAGE < salons.length;

          return (
            <div key={category}>
              <SectionTitle>{category}</SectionTitle>
              <ScrollWrapper>
                <HorizontalScroll ref={(el) => { scrollRefs.current[index] = el; }}>
                  {visibleSalons.map((salon) => (
                    <SalonCard
                      key={`${category}-${salon.id}`}
                      id={salon.id}
                      image={salon.image}
                      name={salon.name}
                      distance={salon.distance}
                      location={salon.location}
                      rating={salon.rating}
                      reviews={salon.reviews}
                      onClick={() =>
                        navigate(`/booking/${salon.id}`, { state: salon })
                      }
                    />
                  ))}
                </HorizontalScroll>

                {/* ✅ Scroll Arrow appears only if there’s more */}
                {hasMore && (
                  <ScrollCircle onClick={() => handleScrollRight(index)}>
                    <ArrowIcon />
                  </ScrollCircle>
                )}
              </ScrollWrapper>
            </div>
          );
        })}
      </ContentWrapper>
    </PageWrapper>
  );
};

export default HomePage;
